@Repository
public class CourseClosure {
    private final JdbcTemplate db;
    public CourseClosure(JdbcTemplate db) {
        this.db = db;
    }

    public void retire(UUID id) {
        // The condition is evaluated atomically with the update.
        int changed = db.update("update course set active = false, revision = revision + 1 "
            + "where id = ? and active = true and open_items = 0", id);
        if (changed == 0) {
            throw new IllegalStateException("Record is unavailable or has unresolved work");
        }
    }
