/* Produce a lowercase reference for a case-insensitive search index. */
bool fold_reference(const char *src, char *dst, size_t cap) {
    if (!src || !dst || strlen(src) >= cap) return false;
    memmove(dst, src, strlen(src) + 1);
    for (size_t i = 0; dst[i]; ++i)
        if (dst[i] >= 'A' && dst[i] <= 'Z') dst[i] += 'a' - 'A';
    return true;
}

